{
  "title": "Great API Experience",
  "content": "The TripRadar API is really easy to use and well-documented. The response times are excellent and the data quality is very good. Would definitely recommend to other developers.",
  "rating": 5,
  "feedbackCategoryType": "General"
}

{
  "title": "Flight Search Returns Stale Data",
  "content": "When searching for flights from JFK to LAX, the API sometimes returns flights from yesterday instead of the requested date. This happens about 20% of the time during peak hours.",
  "rating": 2,
  "feedbackCategoryType": "BugReport"
}

{
  "title": "Add Real-time Price Alerts",
  "content": "It would be great to have a feature that sends webhooks or notifications when flight/hotel prices drop below a certain threshold. This would make the scheduled queries even more valuable.",
  "rating": 4,
  "feedbackCategoryType": "FeatureRequest"
}

